const usedLifelines = `-- name: UsedLifelines :many
SELECT DISTINCT lifeline FROM game_answers
WHERE game_id = $1 AND player_id = $2 AND lifeline IS NOT NULL
`

type UsedLifelinesParams struct {
	GameID   uuid.UUID `json:"game_id"`
	PlayerID uuid.UUID `json:"player_id"`
}

func (q *Queries) UsedLifelines(ctx context.Context, arg UsedLifelinesParams) ([]pgtype.Text, error) {
	rows, err := q.db.Query(ctx, usedLifelines, arg.GameID, arg.PlayerID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []pgtype.Text{}
	for rows.Next() {
		var lifeline pgtype.Text
		if err := rows.Scan(&lifeline); err != nil {
			return nil, err
		}
		items = append(items, lifeline)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
